# Let's analyze each changed pair manually
for i, inp, outp in [(0, 'jdxb', 'jdzb'), (1, 'xkfg', 'zkfg'), (3, 'kix', 'yfb'), (4, 'buwkb', 'bjzfwkb')]:
    print(f"Input: '{inp}' -> Output: '{outp}'")

    # Find differences
    diff_pos = None
    for j, (ch_in, ch_out) in enumerate(zip(inp, outp)):
        if ch_in != ch_out:
            diff_pos = j
            break

    if diff_pos is not None:
        print(f"  Difference at position {diff_pos}: '{inp[diff_pos]}' -> '{outp[diff_pos]}'")
    else:
        # Check if lengths differ
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")
            if len(inp) > len(outp):
                print(f"  Remove substring: '{inp[len(outp):]}'")
            else:
                print(f"  Add substring: '{outp[len(inp):]}'")
    print()

